const messageText = $('Telegram Trigger').item.json.message?.text || '';
const q = String(messageText).trim();

const isImageRequest = /\b(photo|picture|image|wallpaper|avatar|pfp|pic|صورة|خلفية|رمزية)\b/i.test(q);

// استخراج الكلمات اللاتينية (الإنجليزية)
const words = q.replace(/[^\p{L}\p{N}\s.+#-]/gu, ' ')
  .split(/\s+/)
  .filter(w => w.length > 1);

const latinWords = words.filter(w => /^[a-z0-9.+#-]+$/i.test(w));

let keywords = '';

if (latinWords.length > 0) {
  keywords = latinWords.slice(0, 6).join(' ');
} else {
  // إذا كانت الرسالة تقنية وتتضمن استفسار عن مكتبات أو جيت هب باللغة العربية
  if (/جيتهب|جيت هب|مكتبات|مكتبة|مشروع|مشاريع|لغة|برمجة/i.test(q)) {
    keywords = 'awesome OR trending OR tools';
  } else {
    keywords = words.slice(0, 6).join(' ');
  }
}

// تفعيل البحث التقني دائماً إذا كانت الرسالة تقنية وليست طلب صورة
const needsSearch = !isImageRequest && (keywords.length > 0 || q.length >= 5);

return {
  chatInput: q,
  keywords: keywords || 'awesome',
  needsSearch,
  isImageRequest
};

