const messageText = $('Telegram Trigger').item.json.message?.text \vert{}\vert{} '';
const q = String(messageText);

const isImageRequest = /\b(photo\vert{}picture\vert{}image\vert{}wallpaper\vert{}avatar\vert{}pfp\vert{}pic\vert{}صورة\vert{}خلفية\vert{}رمزية)\b/i.test(q);

// فحص ما إذا كان الطلب يتضمن صوراً عالية الدقة جداً مثل 8K لترسل كروابط بدلاً من صورة عادية
const isHighResImage = isImageRequest && /\b(8k\vert{}16k\vert{}ultra\s*hd\vert{}raw)\b/i.test(q);

// استخراج الكلمات اللاتينية (الإنجليزية)
const words = q.replace(/[^\p{L}\p{N}\s.+#-]/gu, ' ')
  .split(/\s+/)
  .filter(w => w.length > 1);

const latinWords = words.filter(w => /^[a-z0-9.+#-]+$/i.test(w));

let keywords = '';

if (latinWords.length > 0) {
  keywords = latinWords.slice(0, 6).join(' ');
} else {
  // إذا كانت الرسالة بالعربية تماماً وتخص جيت هب، نضع كلمات بحث افتراضية بالإنجليزية
  if (/جيتهب|جيت هب|مكتبات|مكتبة|مشروع|مشاريع/i.test(q)) {
    keywords = 'awesome OR trending OR tools';
  } else {
    keywords = words.slice(0, 6).join(' ');
  }
}

const needsSearch = !isImageRequest && words.length >= 2 && q.trim().length >= 8;

return {
  chatInput: q,
  keywords: keywords || '',
  needsSearch,
  isImageRequest,
  isHighResImage // خاصية جديدة لتحديد ما إذا كانت الصورة 8K وترسل كرابط فقط
};

let githubItems = [];
let hnHits = [];

// محاولة جلب بيانات GitHub بأمان دون توقف الكود إذا لم تنفذ العقدة
try {
  githubItems = ($('HTTP Request').item?.json?.items || []).slice(0, 3).map(r => ({
    name: r.full_name,
    url: r.html_url,
    stars: r.stargazers_count,
    desc: r.description ? r.description.slice(0, 100) : ""
  }));
} catch (e) {
  // إذا كان المسار False ولم تتنفذ عقدة HTTP Request، تبقى القائمة فارغة []
  githubItems = [];
}

// محاولة جلب بيانات Hacker News بأمان
try {
  hnHits = ($('HTTP Request1').item?.json?.hits || []).slice(0, 3).map(h => ({
    title: h.title,
    url: h.url,
    points: h.points
  }));
} catch (e) {
  // إذا كان المسار False ولم تتنفذ عقدة HTTP Request1، تبقى القائمة فارغة []
  hnHits = [];
}

return {
  chatInput: $('Extract Search Keywords').item.json.chatInput || '',
  keywords: $('Extract Search Keywords').item.json.keywords || '',
  githubItems: JSON.stringify(githubItems),
  hnHits: JSON.stringify(hnHits)
};
